# Standard library
import uuid

# Third-party
from sqlalchemy import func
from sqlalchemy.orm import Mapped, mapped_column

# Local application
from app.core.base import Base, ReferenceWithFactorMixin


class CoreRefWaypointType(Base, ReferenceWithFactorMixin):
    __tablename__ = "core_ref_waypoint_type"

    id: Mapped[uuid.UUID] = mapped_column(
        primary_key=True,
        server_default=func.gen_random_uuid(),
        description=(
            "Primary key UUID, auto-generated by the database. Uniquely "
            "identifies a waypoint type such as Start, End, Rest Stop, or "
            "Photo Point."
        ),
    )
